from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
SERVER = ROOT / 'server' / 'academy-v3.mjs'
CLIENT = ROOT / 'src' / 'main-v2.jsx'
MARK = 'ACADEMY_ENHANCEMENTS_V2'

s = SERVER.read_text(encoding='utf-8')
c = CLIENT.read_text(encoding='utf-8')
if MARK in s and MARK in c:
    print('enhancements already applied')
    raise SystemExit(0)

# Backend: permissions + persistent settings.
s = s.replace(
"const PERMISSIONS={view_dashboard:'لوحة الإدارة',manage_members:'إدارة الأفراد',manage_applications:'إدارة التقديمات',manage_exams:'إدارة الاختبارات',manage_hierarchy:'إدارة الهيكل',view_evaluations:'الاطلاع على التقييمات',manage_evaluations:'إدارة التقييمات',manage_admins:'إدارة الأدمن',manage_settings:'الإعدادات'};",
"const PERMISSIONS={view_dashboard:'لوحة الإدارة',manage_members:'إدارة الأفراد',manage_applications:'إدارة التقديمات',manage_exams:'إدارة الاختبارات',manage_hierarchy:'إدارة الهيكل',view_evaluations:'الاطلاع على التقييمات',manage_evaluations:'إدارة التقييمات',manage_admins:'إدارة الأدمن',manage_settings:'الإعدادات',delete_applications:'حذف التقديمات',delete_exams:'حذف الاختبارات',delete_evaluations:'حذف التقييمات'};"
)
s = s.replace(
"policeInvite:INVITE},applicationQuestions",
"policeInvite:INVITE,evaluationBatchId:'',evaluationNotice:'التقييمات مستقلة عن حالة التقديمات ويمكن فتحها للدفعة بعد إغلاق التقديم.',},applicationQuestions"
)
# Add a stable evaluation-batch helper next to activeBatch.
s = s.replace(
"function activeBatch(){return data.batches.find(b=>b.status==='open'&&state(b.startAt,b.endAt)==='open')||null}\n",
"function activeBatch(){return data.batches.find(b=>b.status==='open'&&state(b.startAt,b.endAt)==='open')||null}\nfunction evaluationBatch(){const id=String(data.settings?.evaluationBatchId||'');return id?data.batches.find(b=>b.id===id)||null:null}\n"
)

backend_routes = r'''
/* ACADEMY_ENHANCEMENTS_V2 */
app.get('/api/evaluation-context',async(req,res)=>{const c=await current(req);if(!c.x)return res.status(401).json({error:'UNAUTHENTICATED'});let rows=[];try{rows=await police()}catch{return res.status(503).json({error:'POLICE_SHEET_UNAVAILABLE'})}const trainers=rows.filter(trainer).map(r=>({...r}));const trainees=rows.filter(trainee).map(r=>({...r}));const batch=evaluationBatch();res.json({me:c.police?{...c.police}:null,trainers,trainees,batch:batch?{id:batch.id,name:batch.name,status:batch.status,startAt:batch.startAt,endAt:batch.endAt}:null,notice:data.settings?.evaluationNotice||'',canEvaluate:Boolean(c.police&&(trainer(c.police)||trainee(c.police)||c.admin))})});
app.patch('/api/admin/evaluation-batch',async(req,res)=>{const c=await guard(req,res,'manage_evaluations');if(!c)return;const batchId=String(req.body?.batchId||'');if(batchId&&!data.batches.some(b=>b.id===batchId))return res.status(404).json({error:'BATCH_NOT_FOUND'});data.settings.evaluationBatchId=batchId;audit(c,'SET_EVALUATION_BATCH',batchId||'none');await save();res.json({ok:true,batch:batchId?data.batches.find(b=>b.id===batchId):null})});
app.post('/api/evaluations-v2',async(req,res)=>{try{const c=await current(req);if(!c.x||!c.police)return res.status(401).json({error:'UNAUTHENTICATED'});const b=req.body||{},type=String(b.type||''),batch=evaluationBatch();if(!batch)return res.status(409).json({error:'NO_EVALUATION_BATCH'});if(!['trainee_to_trainer','trainer_to_trainee'].includes(type))return res.status(400).json({error:'INVALID_EVALUATION_TYPE'});const rows=await police();const byId=v=>rows.find(r=>id(r.discordId)===id(v));const trainerRow=byId(b.trainerId);const traineeRow=byId(b.traineeId);if(!trainerRow||!trainer(trainerRow))return res.status(400).json({error:'INVALID_TRAINER'});if(!traineeRow||!trainee(traineeRow))return res.status(400).json({error:'INVALID_TRAINEE'});if(type==='trainee_to_trainer'&&!trainee(c.police))return res.status(403).json({error:'TRAINEE_ONLY'});if(type==='trainer_to_trainee'&&!trainer(c.police))return res.status(403).json({error:'TRAINER_ONLY'});const rating=Number(b.rating);if(!Number.isInteger(rating)||rating<1||rating>10)return res.status(400).json({error:'INVALID_RATING'});const required=type==='trainer_to_trainee'?['trainingHours','leadershipRating','citizensRating','devicesRating','reportsRating','weaponsRating','notes']:['trainingHours','cases','trainerView','clarity','trainingNotes','trainerNotes','sameTrainer'];for(const k of required)if(String(b[k]??'').trim()==='')return res.status(400).json({error:'REQUIRED_FIELD_MISSING',field:k});if(type==='trainer_to_trainee'){for(const k of ['leadershipRating','citizensRating','devicesRating','reportsRating','weaponsRating']){const n=Number(b[k]);if(!Number.isInteger(n)||n<1||n>10)return res.status(400).json({error:'INVALID_RATING',field:k})}}else if(!['نعم','لا'].includes(String(b.sameTrainer)))return res.status(400).json({error:'INVALID_SAME_TRAINER'});const ev={id:`eval-${Date.now()}`,type,fromUserId:String(c.x.id),fromName:c.police.name,fromBadge:c.police.badge,fromRank:c.police.rank,toUserId:String(type==='trainer_to_trainee'?traineeRow.discordId:trainerRow.discordId),traineeId:traineeRow.discordId,traineeName:traineeRow.name,traineeBadge:traineeRow.badge,traineeRank:traineeRow.rank,traineeDiscordId:traineeRow.discordId,trainerId:trainerRow.discordId,trainerName:trainerRow.name,trainerBadge:trainerRow.badge,trainerRank:trainerRow.rank,trainerDiscordId:trainerRow.discordId,batchId:batch.id,batchName:batch.name,trainingHours:String(b.trainingHours||''),leadershipRating:String(b.leadershipRating||''),citizensRating:String(b.citizensRating||''),devicesRating:String(b.devicesRating||''),reportsRating:String(b.reportsRating||''),weaponsRating:String(b.weaponsRating||''),notes:String(b.notes||''),cases:String(b.cases||''),trainerView:String(b.trainerView||''),clarity:String(b.clarity||''),trainingNotes:String(b.trainingNotes||''),trainerNotes:String(b.trainerNotes||''),sameTrainer:String(b.sameTrainer||''),rating,reviewStatus:'pending',createdAt:new Date().toISOString()};data.evaluations.unshift(ev);audit(c,'CREATE_EVALUATION',ev.id,`${type}:${batch.name}`);await save();res.json({ok:true,evaluation:ev})}catch(e){console.error(e);res.status(503).json({error:'STORAGE_ERROR'})}});
app.get('/api/admin/exam-results/:id',async(req,res)=>{const c=await guard(req,res,'manage_exams');if(!c)return;const r=data.examResults.find(x=>x.id===req.params.id);if(!r)return res.status(404).json({error:'RESULT_NOT_FOUND'});const exam=data.exams.find(x=>x.id===r.examId);if(!exam)return res.status(404).json({error:'EXAM_NOT_FOUND'});let person=null;try{person=(await police()).find(x=>id(x.discordId)===id(r.userId))||null}catch{}res.json({result:r,exam:{id:exam.id,title:exam.title,description:exam.description,questions:exam.questions},person})});
app.delete('/api/admin/delete/application/:id',async(req,res)=>{const c=await guard(req,res,'delete_applications');if(!c)return;const i=data.applications.findIndex(x=>x.id===req.params.id);if(i<0)return res.status(404).json({error:'APPLICATION_NOT_FOUND'});const [removed]=data.applications.splice(i,1);audit(c,'DELETE_APPLICATION',removed.id,removed.name);await save();res.json({ok:true})});
app.delete('/api/admin/delete/evaluation/:id',async(req,res)=>{const c=await guard(req,res,'delete_evaluations');if(!c)return;const i=data.evaluations.findIndex(x=>x.id===req.params.id);if(i<0)return res.status(404).json({error:'EVALUATION_NOT_FOUND'});const [removed]=data.evaluations.splice(i,1);audit(c,'DELETE_EVALUATION',removed.id,removed.batchName||'');await save();res.json({ok:true})});
app.delete('/api/admin/delete/exam/:id',async(req,res)=>{const c=await guard(req,res,'delete_exams');if(!c)return;const i=data.exams.findIndex(x=>x.id===req.params.id);if(i<0)return res.status(404).json({error:'EXAM_NOT_FOUND'});data.exams.splice(i,1);data.examResults=data.examResults.filter(x=>x.examId!==req.params.id);data.examAttempts=data.examAttempts.filter(x=>x.examId!==req.params.id);audit(c,'DELETE_EXAM',req.params.id);await save();res.json({ok:true})});
app.post('/api/admin/member-image-link',async(req,res)=>{const c=await guard(req,res,'manage_members');if(!c)return;const uid=id(req.body?.discordId),image=String(req.body?.image||'').trim();if(!uid)return res.status(400).json({error:'INVALID_DISCORD_ID'});if(image&&!/^https?:\/\//i.test(image))return res.status(400).json({error:'INVALID_IMAGE_URL'});data.memberImages[uid]=image;audit(c,'UPDATE_MEMBER_IMAGE_LINK',uid);await save();res.json({ok:true,image})});
app.put('/api/admin/ui-settings',async(req,res)=>{const c=await guard(req,res,'manage_settings');if(!c)return;const allowed=['academyName','applicationsTitle','applicationsDescription','policeInvite','evaluationNotice'];for(const k of allowed)if(req.body?.[k]!==undefined)data.settings[k]=String(req.body[k]??'');audit(c,'UPDATE_UI_SETTINGS','settings');await save();res.json({ok:true,settings:data.settings})});
'''
# Put the new routes immediately before load; this keeps them registered after the existing app setup.
s = s.replace('await load();', backend_routes + '\nawait load();', 1)

# Frontend helpers and evaluation page.
new_eval = r'''function ProfileMini({person,label='بياناتك'}){if(!person)return null;return <div className="profileMini"><div><b>{label}</b><span>{person.name||'—'}</span></div><div><small>البادج</small><b>{person.badge||'—'}</b></div><div><small>الرتبة</small><b>{person.rank||'—'}</b></div><div><small>المسؤولية</small><b>{person.responsibility||'—'}</b></div><a className="discordBtn" href={`https://discord.com/users/${person.discordId}`} target="_blank" rel="noreferrer"><ExternalLink size={14}/> Discord</a></div>}
function PersonOption({x}){return <option value={x.discordId}>{x.name} — {x.rank||'—'} — Badge #{x.badge||'—'}</option>}
function EvaluationDetails({x,onClose}){return <div className="modalBackdrop"><div className="modal"><div className="panelHead"><div><span className="eyebrow">EVALUATION DETAILS</span><h2>{x.type==='trainer_to_trainee'?'تقييم المتدرب':'تقييم المدرب'}</h2></div><Button kind="secondary" onClick={onClose}>إغلاق</Button></div><div className="detailGrid"><div><b>الدفعة</b><span>{x.batchName||'—'}</span></div><div><b>التاريخ</b><span>{fmt(x.createdAt)}</span></div><div><b>المدرب</b><span>{x.trainerName} · {x.trainerRank} · Badge #{x.trainerBadge||'—'}</span></div><div><b>المتدرب</b><span>{x.traineeName} · {x.traineeRank} · Badge #{x.traineeBadge||'—'}</span></div><div><b>الساعات</b><span>{x.trainingHours||'—'}</span></div><div><b>التقييم النهائي</b><span>{x.rating}/10</span></div></div><div className="detailAnswers">{[['cases','الحالات'],['trainerView','رؤية المدرب'],['clarity','الوضوح'],['trainingNotes','ملاحظات التدريب'],['trainerNotes','ملاحظات على المدرب'],['sameTrainer','نفس المدرب مرة أخرى'],['leadershipRating','مهارة القيادة'],['citizensRating','التعامل مع المواطنين والزملاء'],['devicesRating','أجهزة الشرطة'],['reportsRating','البلاغات'],['weaponsRating','الأسلحة'],['notes','الملاحظات']].filter(([k])=>x[k]!==undefined&&x[k]!==''&&x[k]!==null).map(([k,l])=><div key={k}><b>{l}</b><p>{String(x[k])}</p></div>)}</div></div></div>}
function Evaluations({user}){const[ctx,setCtx]=useState(null),[tab,setTab]=useState('trainee'),[form,setForm]=useState({}),[logs,setLogs]=useState([]),[msg,setMsg]=useState(''),[detail,setDetail]=useState(null);const load=async()=>{try{const[c,e]=await Promise.all([api('/api/evaluation-context'),api('/api/evaluations')]);setCtx(c);setLogs(e.evaluations||[])}catch(e){setMsg(err(e))}};useEffect(()=>{load()},[]);const set=(k,v)=>setForm(f=>({...f,[k]:v}));const send=async()=>{try{const payload={...form,type:tab==='trainee'?'trainee_to_trainer':'trainer_to_trainee',traineeId:tab==='trainee'?user.police?.discordId:form.traineeId,trainerId:tab==='trainer'?user.police?.discordId:form.trainerId};await api('/api/evaluations-v2',{method:'POST',body:JSON.stringify(payload)});setMsg('تم حفظ التقييم بالتفصيل وربطه بالدفعة المحددة.');setForm({});await load()}catch(e){setMsg(err(e))}};const me=ctx?.me||user.police;const list=logs.filter(x=>!ctx?.batch||x.batchId===ctx.batch.id);return <Page title="التقييمات" sub="التقييمات مستقلة عن التقديمات ويمكن فتحها للدفعة بعد إغلاق التقديم."><div className="activeBatchPill">دفعة التقييم الحالية: <b>{ctx?.batch?.name||'لا توجد دفعة محددة'}</b></div>{ctx?.notice&&<div className="notice">{ctx.notice}</div>}<ProfileMini person={me}/><div className="tabs"><button type="button" className={tab==='trainee'?'active':''} onClick={()=>{setTab('trainee');setForm({})}}>المتدرب → المدرب</button><button type="button" className={tab==='trainer'?'active':''} onClick={()=>{setTab('trainer');setForm({})}}>المدرب → المتدرب</button></div>{!ctx?.batch?<div className="empty"><Star size={38}/><h2>لا توجد دفعة تقييم مفتوحة</h2></div>:<><div className="panel form">{tab==='trainee'?<><h2>تقييم المدرب</h2><Field label="المدرب"><select value={form.trainerId||''} onChange={e=>set('trainerId',e.target.value)}><option value="">اختر المدرب</option>{(ctx.trainers||[]).map(x=><PersonOption x={x} key={x.discordId}/>)}</select></Field><Field label="عدد ساعات التدريب"><input value={form.trainingHours||''} onChange={e=>set('trainingHours',e.target.value)}/></Field><Field label="ما هي الحالات التي باشرت فيها؟"><textarea value={form.cases||''} onChange={e=>set('cases',e.target.value)}/></Field><Field label="كيف ترى المدرب؟"><textarea value={form.trainerView||''} onChange={e=>set('trainerView',e.target.value)}/></Field><Field label="هل كان المدرب واضحًا؟"><textarea value={form.clarity||''} onChange={e=>set('clarity',e.target.value)}/></Field><Field label="ملاحظات في التدريب"><textarea value={form.trainingNotes||''} onChange={e=>set('trainingNotes',e.target.value)}/></Field><Field label="ملاحظات على المدرب"><textarea value={form.trainerNotes||''} onChange={e=>set('trainerNotes',e.target.value)}/></Field><Field label="تريد نفس المدرب مرة أخرى؟"><div className="choiceGrid"><button type="button" className={form.sameTrainer==='نعم'?'selected':''} onClick={()=>set('sameTrainer','نعم')}>نعم</button><button type="button" className={form.sameTrainer==='لا'?'selected':''} onClick={()=>set('sameTrainer','لا')}>لا</button></div></Field><Rating value={form.rating} set={v=>set('rating',v)}/></>:<><h2>تقييم المتدرب</h2><Field label="المتدرب"><select value={form.traineeId||''} onChange={e=>set('traineeId',e.target.value)}><option value="">اختر المتدرب</option>{(ctx.trainees||[]).map(x=><PersonOption x={x} key={x.discordId}/>)}</select></Field><Field label="عدد ساعات التدريب"><input value={form.trainingHours||''} onChange={e=>set('trainingHours',e.target.value)}/></Field>{[['leadershipRating','مهارة القيادة'],['citizensRating','التعامل مع المواطنين والزملاء'],['devicesRating','التعامل مع أجهزة الشرطة'],['reportsRating','التعامل مع البلاغات'],['weaponsRating','التعامل مع الأسلحة']].map(([k,l])=><Field key={k} label={l}><Rating value={form[k]} set={v=>set(k,v)}/></Field>)}<Field label="ملاحظات"><textarea value={form.notes||''} onChange={e=>set('notes',e.target.value)}/></Field><Rating label="التقييم النهائي" value={form.rating} set={v=>set('rating',v)}/></>}</div><Button onClick={send}><Save/> حفظ التقييم</Button></>}{msg&&<div className="notice">{msg}</div>}<div className="panel log"><div className="panelHead"><div><h2>سجل التقييمات</h2><span>{list.length} تقييم</span></div></div>{list.map(x=><div className="evaluationAdminRow" key={x.id}><div><b>{x.fromName} → {x.type==='trainer_to_trainee'?x.traineeName:x.trainerName}</b><small>{x.batchName||'دفعة'} · {x.trainerRank||'—'} · Badge #{x.trainerBadge||'—'} · {fmt(x.createdAt)} · {x.rating}/10</small></div><div className="actions"><Button kind="secondary" onClick={()=>setDetail(x)}>التفاصيل</Button></div></div>)}</div>{detail&&<EvaluationDetails x={detail} onClose={()=>setDetail(null)}/>}</Page>}
'''
c = re.sub(r'function Evaluations\(\{user\}\).*?(?=function Rating\()', new_eval, c, flags=re.S)

# Richer admin batches.
new_batches = r'''function AdminBatches({s,reload}){const[b,setB]=useState({name:'',startAt:'',endAt:''}),[selected,setSelected]=useState(null),[evalBatch,setEvalBatch]=useState(s.settings?.evaluationBatchId||'');const create=async()=>{await api('/api/admin/batches',{method:'POST',body:JSON.stringify(b)});setB({name:'',startAt:'',endAt:''});reload()};const review=async(a,status)=>{await api(`/api/admin/applications/${a.id}`,{method:'PATCH',body:JSON.stringify({status,note:a.reviewNote||''})});reload()};const saveEval=async(id)=>{await api('/api/admin/evaluation-batch',{method:'PATCH',body:JSON.stringify({batchId:id})});setEvalBatch(id);reload()};return <div className="stack"><div className="panel"><h2>فتح دفعة جديدة</h2><div className="gridForm"><input placeholder="اسم الدفعة" value={b.name} onChange={e=>setB({...b,name:e.target.value})}/><input type="datetime-local" value={b.startAt} onChange={e=>setB({...b,startAt:e.target.value})}/><input type="datetime-local" value={b.endAt} onChange={e=>setB({...b,endAt:e.target.value})}/><Button onClick={create}><Plus/> إنشاء الدفعة</Button></div></div><div className="panel"><div className="panelHead"><div><h2>دفعة التقييم</h2><small>مستقلة عن فتح التقديمات. أغلق التقديم ثم اترك التقييم مفتوحًا لهذه الدفعة.</small></div></div><div className="gridForm"><select value={evalBatch} onChange={e=>saveEval(e.target.value)}><option value="">لا توجد دفعة تقييم</option>{s.batches.map(x=><option value={x.id} key={x.id}>{x.name} · {x.status==='open'?'التقديم مفتوح':'التقديم مغلق'}</option>)}</select></div></div>{s.batches.map(b=>{const apps=s.applications.filter(a=>a.batchId===b.id);return <div className="panel batchPanel" key={b.id}><div className="panelHead"><div><span className="eyebrow">BATCH</span><h2>{b.name}</h2><small>{fmt(b.startAt)} → {fmt(b.endAt)}</small></div><div className="batchStats"><b>{apps.length}</b><span>طلبات</span><Status value={b.status}/>{evalBatch===b.id&&<span className="status accepted">دفعة التقييم</span>}</div></div><div className="statusCounts"><span>مراجعة {apps.filter(a=>a.status==='pending').length}</span><span>مقبول {apps.filter(a=>a.status==='accepted').length}</span><span>مرفوض {apps.filter(a=>a.status==='rejected').length}</span><span>انتظار {apps.filter(a=>a.status==='waitlist').length}</span></div><div className="actions"><Button kind="secondary" onClick={()=>setSelected(selected===b.id?null:b.id)}>{selected===b.id?'إخفاء الطلبات':'فتح طلبات الدفعة'}</Button><Button kind={b.status==='open'?'danger':'secondary'} onClick={async()=>{await api(`/api/admin/batches/${b.id}`,{method:'PATCH',body:JSON.stringify({status:b.status==='open'?'closed':'open'})});reload()}}>{b.status==='open'?'إغلاق التقديم':'فتح التقديم'}</Button>{evalBatch!==b.id&&<Button kind="secondary" onClick={()=>saveEval(b.id)}>فتح التقييم لهذه الدفعة</Button>}{evalBatch===b.id&&<Button kind="danger" onClick={()=>saveEval('')}>إغلاق التقييم</Button>}</div>{selected===b.id&&<div className="appList">{apps.map(a=><ApplicationAdmin key={a.id} a={a} s={s} review={review} reload={reload}/>)}</div>}</div>})}</div>}
function ApplicationAdmin({a,s,review,reload}){const q=s.applicationQuestions;return <details className="appAdmin"><summary><div><b>{a.name}</b><small>Discord: {a.discordId} · {fmt(a.submittedAt)}</small></div><Status value={a.status}/></summary><div className="answerList">{q.map(x=><div key={x.id}><b>{x.text}</b><p>{String(a.answers?.[x.id]??'—')}</p></div>)}<a className="discordBtn" href={`https://discord.com/users/${a.discordId}`} target="_blank" rel="noreferrer"><ExternalLink size={14}/> فتح Discord</a><textarea placeholder="ملاحظة المراجع" value={a.reviewNote||''} onChange={e=>a.reviewNote=e.target.value}/><div className="actions"><Button onClick={()=>review(a,'accepted')}>قبول</Button><Button kind="secondary" onClick={()=>review(a,'waitlist')}>انتظار</Button><Button kind="danger" onClick={()=>review(a,'rejected')}>رفض</Button><Button kind="danger" onClick={async()=>{if(confirm('حذف طلب التقديم نهائيًا؟')){await api(`/api/admin/delete/application/${a.id}`,{method:'DELETE'});reload()}}}><Trash2/> حذف الطلب</Button></div></div></details>}
'''
c = re.sub(r'function AdminBatches\(\{s,reload\}\).*?(?=function AdminQuestions\()', new_batches, c, flags=re.S)

# Detailed exam result UI and deletion.
new_exams = r'''function ExamResultDetails({item,onClose}){const[r,setR]=useState(null),[loading,setLoading]=useState(true),[msg,setMsg]=useState('');useEffect(()=>{api(`/api/admin/exam-results/${item.id}`).then(setR).catch(e=>setMsg(err(e))).finally(()=>setLoading(false))},[item.id]);return <div className="modalBackdrop"><div className="modal"><div className="panelHead"><div><span className="eyebrow">EXAM RESULT DETAILS</span><h2>{item.name||'نتيجة اختبار'}</h2></div><Button kind="secondary" onClick={onClose}>إغلاق</Button></div>{loading?<div className="empty">جاري تحميل التفاصيل…</div>:msg?<div className="notice">{msg}</div>:<><ProfileMini person={r.person} label="بيانات المتقدم"/><div className="detailGrid"><div><b>الاختبار</b><span>{r.exam.title}</span></div><div><b>النتيجة</b><span>{r.result.score}%</span></div><div><b>التاريخ</b><span>{fmt(r.result.submittedAt)}</span></div></div><div className="detailAnswers">{r.exam.questions.map((q,i)=><div key={q.id}><b>{i+1}. {q.text}</b><p>الإجابة: {String(r.result.answers?.[q.id]??'—')}</p>{q.correct&&<small>الإجابة الصحيحة: {q.options?.find(o=>o.id===q.correct)?.text||q.correct}</small>}</div>)}</div></>}</div></div>}
function AdminExams({s,reload}){const[selected,setSelected]=useState(null),[result,setResult]=useState(null);const create=async()=>{const d=await api('/api/admin/exams',{method:'POST',body:JSON.stringify({title:'اختبار جديد'})});setSelected(d.exam.id);reload()};const visibility=async(r,visible)=>{await api(`/api/admin/exam-results/${r.id}/visibility`,{method:'PATCH',body:JSON.stringify({visible})});reload()};return <div className="stack"><div className="panelHead"><h2>إدارة الاختبارات</h2><Button onClick={create}><Plus/> إنشاء اختبار</Button></div>{s.exams.map(e=><ExamEditor e={e} key={e.id} reload={reload} open={selected===e.id} onOpen={()=>setSelected(e.id)}/>) }<div className="panel"><div className="panelHead"><div><h2>نتائج الاختبارات</h2><small>اضغط التفاصيل لرؤية الأسئلة والإجابات كاملة.</small></div><span>{s.examResults.length} نتيجة</span></div>{s.examResults.map(r=><div className="resultAdminRow" key={r.id}><div><b>{r.name||r.userId}</b><small>{s.exams.find(e=>e.id===r.examId)?.title||r.examId} · {fmt(r.submittedAt)} · {r.score}%</small></div><a className="discordBtn" href={`https://discord.com/users/${r.userId}`} target="_blank" rel="noreferrer"><ExternalLink size={14}/> Discord</a><Status value={r.passed?'accepted':'rejected'}/><div className="actions"><Button kind="secondary" onClick={()=>setResult(r)}>التفاصيل</Button><Button kind={r.resultVisible?'secondary':'primary'} onClick={()=>visibility(r,!r.resultVisible)}>{r.resultVisible?'إخفاء النتيجة':'إظهار النتيجة'}</Button><Button kind="danger" onClick={async()=>{if(confirm('حذف الاختبار ونتيجته؟')){await api(`/api/admin/delete/exam/${r.examId}`,{method:'DELETE'});reload()}}}><Trash2/></Button></div></div>)}</div>{result&&<ExamResultDetails item={result} onClose={()=>setResult(null)}/>}</div>}
'''
c = re.sub(r'function AdminExams\(\{s,reload\}\).*?(?=function ExamEditor\()', new_exams, c, flags=re.S)

# Image editor becomes a Discord CDN URL field instead of upload/base64.
new_img = r'''function ImageEditor({value,set}){return <div className="imageUrlEditor"><input value={value||''} onChange={e=>set(e.target.value)} placeholder="رابط صورة Discord CDN"/><small>ضع رابط https://cdn.discordapp.com/... مباشرة.</small>{value&&<img src={value} alt="معاينة"/>}</div>}
'''
c = re.sub(r'function ImageEditor\(\{value,set\}\).*?(?=function AdminMembers\()', new_img, c, flags=re.S)

new_members = r'''function AdminMembers({s,reload}){const[m,setM]=useState(s.members||[]);const save=async x=>{await api('/api/admin/member-image-link',{method:'POST',body:JSON.stringify({discordId:x.discordId,image:x.image||''})});reload()};return <div className="stack"><div className="panel"><h2>صور الأفراد</h2><p className="muted">الصور تحفظ كرابط Discord CDN فقط، بدون رفع ملفات إلى الموقع.</p></div>{m.map(x=><div className="panel memberEdit" key={x.discordId}><div className="avatar">{x.image?<img src={x.image} alt=""/>:<UserRound/>}</div><div><b>{x.name}</b><span>{x.rank} · Badge #{x.badge||'—'}</span></div><a className="discordBtn" href={`https://discord.com/users/${x.discordId}`} target="_blank" rel="noreferrer"><ExternalLink size={14}/> Discord</a><ImageEditor value={x.image} set={v=>{x.image=v;setM([...m])}}/><Button onClick={()=>save(x)}><Save/></Button><Button kind="danger" onClick={()=>{x.image='';setM([...m]);save(x)}}><Trash2/></Button></div>)}</div>}
'''
c = re.sub(r'function AdminMembers\(\{s,reload\}\).*?(?=function AdminAdmins\()', new_members, c, flags=re.S)

# Hierarchy editor with URL input and Discord link.
new_hierarchy = r'''function AdminHierarchy({s,reload,setHier}){const[h,setH]=useState(s.hierarchy||[]);const save=async()=>{const d=await api('/api/admin/hierarchy',{method:'POST',body:JSON.stringify({items:h})});setHier(d.hierarchy);reload()};const add=()=>setH([...h,{id:`hier-${Date.now()}`,title:'مسؤولية جديدة',name:'',discordId:'',image:'',order:h.length+1}]);return <div className="stack"><div className="panelHead"><h2>هيكل الأكاديمية</h2><Button onClick={add}><Plus/> إضافة شخص</Button></div>{h.sort((a,b)=>(a.order||0)-(b.order||0)).map((x,i)=><div className="panel hierarchyEdit" key={x.id}><div className="drag">{i+1}</div><input value={x.title} onChange={e=>{x.title=e.target.value;setH([...h])}}/><input value={x.name} onChange={e=>{x.name=e.target.value;setH([...h])}} placeholder="الاسم"/><input value={x.discordId} onChange={e=>{x.discordId=e.target.value;setH([...h])}} placeholder="Discord ID"/><ImageEditor value={x.image} set={v=>{x.image=v;setH([...h])}}/>{x.discordId&&<a className="discordBtn" href={`https://discord.com/users/${x.discordId}`} target="_blank" rel="noreferrer">Discord <ExternalLink size={14}/></a>}<Button kind="danger" onClick={()=>setH(h.filter(y=>y.id!==x.id))}><Trash2/></Button></div>)}<Button onClick={save}><Save/> حفظ الهيكل</Button></div>}
'''
c = re.sub(r'function AdminHierarchy\(\{s,reload,setHier\}\).*?(?=function ImageEditor\()', new_hierarchy, c, flags=re.S)

# Admin settings panel and admin tabs.
new_admin = r'''function AdminSettings({s,reload}){const[x,setX]=useState({academyName:s.settings?.academyName||'',applicationsTitle:s.settings?.applicationsTitle||'',applicationsDescription:s.settings?.applicationsDescription||'',policeInvite:s.settings?.policeInvite||'',evaluationNotice:s.settings?.evaluationNotice||''});const save=async()=>{await api('/api/admin/ui-settings',{method:'PUT',body:JSON.stringify(x)});reload()};return <div className="panel form"><h2>إعدادات النصوص والروابط</h2><p className="muted">أي جملة أو رابط يتغير من هنا بدون تعديل الكود.</p><Field label="اسم الأكاديمية"><input value={x.academyName} onChange={e=>setX({...x,academyName:e.target.value})}/></Field><Field label="عنوان التقديمات"><input value={x.applicationsTitle} onChange={e=>setX({...x,applicationsTitle:e.target.value})}/></Field><Field label="وصف التقديمات"><textarea value={x.applicationsDescription} onChange={e=>setX({...x,applicationsDescription:e.target.value})}/></Field><Field label="رابط Discord"><input value={x.policeInvite} onChange={e=>setX({...x,policeInvite:e.target.value})}/></Field><Field label="جملة التقييمات"><textarea value={x.evaluationNotice} onChange={e=>setX({...x,evaluationNotice:e.target.value})}/></Field><Button onClick={save}><Save/> حفظ الإعدادات</Button></div>}
function Admin({user,setHier}){const[t,setT]=useState('dashboard'),[s,setS]=useState(null),[msg,setMsg]=useState('');const load=async()=>{try{setS(await api('/api/admin/state'));setMsg('')}catch(e){setMsg(err(e))}};useEffect(()=>{load()},[]);if(!s)return <Page title="مركز الإدارة" sub="إدارة الأكاديمية والصلاحيات."><div className="empty">{msg||'جاري تحميل الإدارة…'}</div><Button onClick={load}><RefreshCw/> إعادة المحاولة</Button></Page>;const can=p=>user.permissions?.adminPermissions?.includes(p)||user.permissions?.adminPermissions?.length===0;return <Page title="مركز الإدارة" sub="إدارة كاملة للتقديمات والدفعات والاختبارات والتقييمات والإعدادات."><div className="tabs adminTabs">{[['dashboard','ملخص'],['batches','الدفعات والتقديمات'],['questions','أسئلة التقديم'],['exams','الاختبارات والنتائج'],['evaluations','التقييمات'],['hierarchy','هيكل الأكاديمية'],['members','الأفراد والصور'],['admins','الأدمن'],['settings','الإعدادات']].map(x=><button type="button" className={t===x[0]?'active':''} onClick={()=>setT(x[0])} key={x[0]}>{x[1]}</button>)}</div>{t==='dashboard'?<AdminDashboard s={s}/>:t==='batches'?<AdminBatches s={s} reload={load}/>:t==='questions'?<AdminQuestions s={s} reload={load}/>:t==='exams'?<AdminExams s={s} reload={load}/>:t==='evaluations'?<AdminEval s={s} reload={load}/>:t==='hierarchy'?<AdminHierarchy s={s} reload={load} setHier={setHier}/>:t==='members'?<AdminMembers s={s} reload={load}/>:t==='settings'?<AdminSettings s={s} reload={load}/>:<AdminAdmins s={s} reload={load}/>} {msg&&<div className="notice">{msg}</div>}</Page>}
'''
c = re.sub(r'function Admin\(\{user,setHier\}\).*?(?=function AdminDashboard\()', new_admin, c, flags=re.S)

# Detailed admin evaluations with deletion and Discord links.
new_admineval = r'''function AdminEval({s,reload}){const[batch,setBatch]=useState('all'),[detail,setDetail]=useState(null);const batches=[...new Map(s.evaluations.map(e=>[e.batchId,{id:e.batchId,name:e.batchName||e.batchId}])).values()];const list=s.evaluations.filter(e=>batch==='all'||e.batchId===batch);const review=async(e,status)=>{await api(`/api/admin/evaluations/${e.id}/review`,{method:'PATCH',body:JSON.stringify({status})});reload()};const remove=async(e)=>{if(confirm('حذف التقييم نهائيًا؟')){await api(`/api/admin/delete/evaluation/${e.id}`,{method:'DELETE'});reload()}};return <div className="panel log"><div className="panelHead"><div><h2>سجل التقييمات</h2><small>التقييمات مفصلة ويمكن فتح بيانات المدرب والمتدرب والأسئلة والإجابات.</small></div><select value={batch} onChange={e=>setBatch(e.target.value)}><option value="all">كل الدفعات</option>{batches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></div>{list.map(e=><div className="evaluationAdminRow" key={e.id}><div><b>{e.fromName} → {e.type==='trainer_to_trainee'?e.traineeName:e.trainerName}</b><small>{e.batchName||'دفعة'} · المدرب: {e.trainerRank||'—'} · Badge #{e.trainerBadge||'—'} · المتدرب: {e.traineeRank||'—'} · Badge #{e.traineeBadge||'—'} · {fmt(e.createdAt)} · {e.rating}/10</small></div><div className="actions"><a className="discordBtn" href={`https://discord.com/users/${e.fromUserId}`} target="_blank" rel="noreferrer"><ExternalLink size={14}/> Discord</a><Button kind="secondary" onClick={()=>setDetail(e)}>التفاصيل</Button><Button kind="secondary" onClick={()=>review(e,'approved')}>اعتماد</Button><Button kind="secondary" onClick={()=>review(e,'rejected')}>رفض</Button><Button kind="danger" onClick={()=>remove(e)}><Trash2/></Button></div></div>)}{detail&&<EvaluationDetails x={detail} onClose={()=>setDetail(null)}/>}</div>}
'''
c = re.sub(r'function AdminEval\(\{s,reload\}\).*?(?=function AdminHierarchy\()', new_admineval, c, flags=re.S)

# Mark modified files.
s = s.rstrip() + '\n'
c = c.rstrip() + '\n'
SERVER.write_text(s,encoding='utf-8')
CLIENT.write_text(c,encoding='utf-8')
print('patched server and client')
